    c0,c1 = min(c for r,c in cells), max(c for r,c in cells)
    marks = [(r,c) for r in range(h) for c in range(w) if grid[r][c] not in (0,2)]
    # A marker outside the block directs the block color along its row/column,
    # continuing from the block toward that grid edge. Markers within the block's
    # row/column leave the block and continue outwards on the corresponding side.
    for r,c in marks:
        if r0 <= r <= r1:
            for x in (range(0,c0) if c < c0 else range(c1+1,w) if c > c1 else []):
                if grid[r][x] == 0: out[r][x] = 2
